house:
# A simple example house: living room, kitchen, dining/entrance, bedroom and bathroom.
# Units are metres. Coordinates are [x, z] on the floor plan (y is up).
name: Simple House
frontBearing: 180

view:
  azimuth: -45
  elevation: 38
  size: 17
  default: ground

walls:
  height: 2.6
  interiorHeight: 1.25
  exteriorThickness: 0.2
  interiorThickness: 0.1
  color: "#efe6d8"
floorHeight: 2.9

floors:
  - id: ground
    name: Ground floor
    rooms:
      - {id: living, name: Living Room, rect: [0, 0, 5, 4], floor: "#c9a47a"}
      - {id: kitchen, name: Kitchen, rect: [5, 0, 4, 4], floor: "#ddd6c8"}
      - {id: dining, name: Dining and Entrance, rect: [5, 4, 4, 3], floor: "#d9d6cf"}
      - {id: bedroom, name: Bedroom, rect: [0, 4, 3, 3], floor: "#c9b9a2"}
      - {id: bathroom, name: Bathroom, rect: [3, 4, 2, 3], floor: "#cfd8d6"}
      - {id: lawn_back, name: Garden, rect: [-4, -4, 17, 4], floor: "#7fae5d", outdoor: true}
      - {id: lawn_left, name: Garden, rect: [-4, 0, 4, 7], floor: "#7fae5d", outdoor: true}
      - {id: lawn_right, name: Garden, rect: [9, 0, 4, 7], floor: "#7fae5d", outdoor: true}
      - {id: lawn_front_left, name: Garden, rect: [-4, 7, 10.1, 4], floor: "#7fae5d", outdoor: true}
      - {id: path, name: Path, rect: [6.1, 7, 1, 4], floor: "#cdbf9f", outdoor: true}
      - {id: lawn_front_right, name: Garden, rect: [7.1, 7, 5.9, 4], floor: "#7fae5d", outdoor: true}
    wallList:
      - {from: [0, 0], to: [9, 0], exterior: true, outerColor: "#e9e7e2", openings: [{type: window, at: 1.6, width: 1.8, sill: 0.8, top: 2.1}, {type: window, at: 5.2, width: 1.0, sill: 1.0, top: 2.1}]}
      - {from: [9, 0], to: [9, 7], exterior: true, outerColor: "#9c5a45", openings: [{type: window, at: 1.4, width: 1.2, sill: 1.0, top: 2.1}, {type: window, at: 5.2, width: 1.2, sill: 0.8, top: 2.1}]}
      - {from: [9, 7], to: [0, 7], exterior: true, outerColor: "#e9e7e2", openings: [{type: door, at: 2.0, width: 0.95, leaf: "#2c3550", transom: true}, {type: window, at: 0.2, width: 1.0, sill: 0.8, top: 2.1}, {type: window, at: 4.3, width: 0.6, sill: 1.2, top: 2.0}, {type: window, at: 6.6, width: 1.5, sill: 0.8, top: 2.1}]}
      - {from: [0, 7], to: [0, 0], exterior: true, outerColor: "#9c5a45", openings: [{type: window, at: 4.2, width: 1.6, sill: 0.6, top: 2.1}]}
      - {from: [5, 0], to: [5, 7], openings: [{type: door, at: 1.2, width: 1.0, open: 0}]}
      - {from: [0, 4], to: [5, 4], openings: [{type: door, at: 2.0, width: 0.8}, {type: door, at: 3.6, width: 0.8}]}
      - {from: [5, 4], to: [9, 4], openings: [{type: door, at: 1.5, width: 1.0, open: 0}]}
      - {from: [3, 4], to: [3, 7]}
    objects:
      # living room
      - {id: living_rug, model: rug, at: [2.4, 2.1], params: {size: [2.8, 1.9], color: "#8a9bb0"}}
      - {id: living_sofa, model: sofa, at: [2.4, 0.6]}
      - {id: living_coffee_table, model: coffee_table, at: [2.4, 1.9]}
      - {id: living_tv_bench, model: tv_bench, at: [2.4, 3.7], rot: 180}
      - {id: living_tv, model: samsung_tv, kind: media_player, at: [2.4, 0.44, 3.7], rot: 180}
      - {id: living_armchair, model: poang_chair, at: [4.4, 3.0], rot: -90}
      - {id: living_floor_lamp, model: floor_lamp, kind: light, at: [0.45, 0.45]}
      - {id: living_plant, model: plant, at: [4.5, 0.45]}
      - {id: living_ceiling, model: ceiling_light, kind: light, at: [2.5, 2.0]}
      - {id: living_cat, model: calico_cat, kind: pet, at: [3.4, 2.5]}
      - {id: living_heater, model: philips_heater, kind: climate, at: [0.6, 2.0]}
      # kitchen
      - {id: kitchen_sink, model: kitchen_unit, at: [5.4, 0.4], params: {width: 0.6, type: sink}}
      - {id: kitchen_drawers, model: kitchen_unit, at: [5.975, 0.4], params: {width: 0.55, type: drawers}}
      - {id: kitchen_oven, model: kitchen_unit, at: [6.55, 0.4], params: {width: 0.6, type: oven}}
      - {id: kitchen_doors_1, model: kitchen_unit, at: [7.15, 0.4], params: {width: 0.6, type: doors}}
      - {id: kitchen_doors_2, model: kitchen_unit, at: [7.9, 0.4], params: {width: 0.9, type: doors}}
      - {id: kitchen_fridge, model: kitchen_tall, at: [8.65, 0.4], params: {width: 0.52, kind: fridge, height: 2.1}}
      - {id: kitchen_coffee, model: coffee_machine, at: [7.9, 0.86, 0.4]}
      - {id: kitchen_table, model: round_dining, at: [7.1, 2.7]}
      - {id: kitchen_light, model: ceiling_light, kind: light, at: [7, 2.4]}
      # dining and entrance
      - {id: dining_set, model: dining_set, at: [7.7, 5.3]}
      - {id: dining_doormat, model: rug, at: [6.6, 6.5], params: {size: [0.8, 0.5], color: "#2b2b2e"}}
      - {id: dining_plant, model: plant, at: [8.55, 6.5]}
      - {id: dining_light, model: ceiling_light, kind: light, at: [7.7, 5.3]}
      # bedroom
      - {id: bedroom_rug, model: rug, at: [1.5, 5.8], params: {size: [2.4, 2.0], color: "#4a4747"}}
      - {id: bedroom_bed, model: bed, at: [1.2, 5.8], rot: 90}
      - {id: bedroom_nightstand, model: nightstand, at: [0.35, 4.6]}
      - {id: bedroom_wardrobe, model: wardrobe, at: [2.62, 6.0], rot: -90}
      - {id: bedroom_light, model: ceiling_light, kind: light, at: [1.5, 5.5]}
      # bathroom
      - {id: bath_tub, model: bathtub, at: [4.0, 6.5], rot: 180}
      - {id: bath_toilet, model: toilet, at: [4.8, 5.3], rot: -90}
      - {id: bath_vanity, model: vanity, at: [3.3, 5.4], rot: 90}
      - {id: bath_light, model: ceiling_light, kind: light, at: [4.0, 5.3]}
      # garden
      - {id: oak_1, model: oak_tree, at: [-2, 0, -2.2], params: {height: 8, crown: 4, seed: 1}}
      - {id: oak_2, model: oak_tree, at: [11.2, 0, -1.8], params: {height: 9, crown: 4.5, seed: 2}}
      - {id: bush_1, model: bush, at: [-1.2, 3.5], params: {size: 1}}
      - {id: bush_2, model: bush, at: [10.5, 3.8], params: {size: 1.2}}
      - {id: bush_3, model: bush, at: [3.5, 8.2], params: {size: 0.8}}
      - {id: street_lamp_1, model: street_lamp, kind: streetlight, at: [8.8, 0, 10.2], rot: 180}

  # flat roof: only shown in the outside view, so the rooms stay visible when a floor is selected
  - id: roof
    name: Roof
    outsideOnly: true
    walls: {height: 0.3, color: "#4a4038"}
    slabColor: "#4a4038"
    rooms:
      - {id: roof, name: Roof, rect: [0, 0, 9, 7], floor: "#5d6066"}
    wallList:
      - {from: [0, 0], to: [9, 0], exterior: true}
      - {from: [9, 0], to: [9, 7], exterior: true}
      - {from: [9, 7], to: [0, 7], exterior: true}
      - {from: [0, 7], to: [0, 0], exterior: true}
    objects:
      - {id: roof_solar_1, model: solar_panel, at: [1.6, 2.0]}
      - {id: roof_solar_2, model: solar_panel, at: [2.8, 2.0]}
      - {id: roof_solar_3, model: solar_panel, at: [4.0, 2.0]}
      - {id: roof_chimney, model: box, at: [7.6, 0, 1.4], params: {size: [0.6, 1.1, 0.6], color: "#9c5a45"}}
